import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        enableEdgeToEdge()

        setContent {
            JFrancoTheme {
                Scaffold(modifier = Modifier.fillMaxSize()) { innerPadding ->
                    Box(modifier = Modifier
                        .fillMaxSize()
                        .padding(innerPadding)) {
                        AppNavigation()
                    }
                }
            }
        }
    }
}

package com.example.compose1.data.di

import com.example.compose1.data.repository.MovieRepositoryImpl
import com.example.compose1.domain.repository.MovieRepository
import dagger.Binds
import dagger.Module
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
abstract class RepositoryModule {

    @Binds
    @Singleton
    abstract fun bindMovieRepository(
        repositoryImpl: MovieRepositoryImpl
    ): MovieRepository
}

package com.example.compose1.data.mapper

import com.example.compose1.data.remote.dto.MovieDto
import com.example.compose1.domain.model.Movie

private const val TMDB_IMAGE_BASE_URL = "https://image.tmdb.org/t/p/w500"

fun MovieDto.toDomain(): Movie {
    val posterUrl = posterPath?.let { "$TMDB_IMAGE_BASE_URL$it" }
    return Movie(
        id = id,
        title = title,
        overview = overview,
        posterUrl = posterUrl
    )
}

package com.example.compose1.data.remote.api

import com.example.compose1.data.remote.dto.PopularMoviesResponseDto
import retrofit2.http.GET
import retrofit2.http.Query

interface TmdbApiService {
    @GET("movie/popular")
    suspend fun getPopularMovies(
        @Query("page") page: Int = 1,
        @Query("language") language: String = "en-US"
    ): PopularMoviesResponseDto
}

package com.example.compose1.data.remote.dto

import com.google.gson.annotations.SerializedName

data class PopularMoviesResponseDto(
    @SerializedName("results")
    val results: List<MovieDto>
)

data class MovieDto(
    @SerializedName("id")
    val id: Int,
    @SerializedName("title")
    val title: String,
    @SerializedName("overview")
    val overview: String,
    @SerializedName("poster_path")
    val posterPath: String?
)

package com.example.compose1.domain.common

sealed interface NetworkResult<out T> {
    data class Success<T>(val data: T) : NetworkResult<T>
    data class Error(val message: String, val throwable: Throwable? = null) : NetworkResult<Nothing>
}

package com.example.compose1.domain.repository

import com.example.compose1.domain.common.NetworkResult
import com.example.compose1.domain.model.Movie

interface MovieRepository {
    suspend fun getPopularMovies(page: Int = 1): NetworkResult<List<Movie>>
}

package com.example.compose1.domain.usecase

import com.example.compose1.domain.repository.MovieRepository
import javax.inject.Inject

class GetPopularMoviesUseCase @Inject constructor(
    private val repository: MovieRepository
) {
    suspend operator fun invoke(page: Int = 1) = repository.getPopularMovies(page = page)
}

